  static FAQS = [
    { q: { de: 'Kann ich den Preis selbst durchrechnen?', en: 'Can I work out the price myself?' }, a: { de: 'Ja. Im Konfigurator wählen Sie Leistung und Umfang und sehen sofort Größenordnung, Dauer und Betriebskosten – dieselbe Rechnung, die wir intern anstellen. Am Ende nehmen Sie die Zusammenfassung als PDF mit oder schicken sie uns direkt.', en: 'Yes. In the configurator you pick the service and the scope and immediately see ballpark, duration and running costs — the same maths we run internally. At the end you take the summary as a PDF or send it straight to us.' }, link: { de: 'Konfigurator öffnen', en: 'Open the configurator' }, href: 'pricing' },
    { q: { de: 'Was kostet ein Projekt?', en: 'What does a project cost?' }, a: { de: 'Es gibt keine Preisliste. Innerhalb von 48 Stunden nach Ihrer Beschreibung erhalten Sie ein Festpreisangebot – eine konkrete Zahl, keine Spanne, die sich später verdoppelt. Eine kleine Website beginnt im niedrigen fünfstelligen Bereich; ein KI-Werkzeug auf Ihren Daten kostet mehr, weil die Arbeit in den Daten steckt, nicht im Modell.', en: 'There is no price list. Within 48 hours of your description you receive a fixed quote — a concrete number, not a range that doubles later. A small website starts in the low five figures; an AI tool on your data costs more, because the work is in the data, not in the model.' } },
    { q: { de: 'Wie lange dauert es?', en: 'How long does it take?' }, a: { de: 'Marketing-Website 3–6 Wochen. Web-App-MVP 6–12 Wochen. KI-Werkzeug auf Ihren Daten 4–10 Wochen, je nach Zustand der Daten. Interne Software 8–14 Wochen. In der ersten Woche sehen Sie etwas Klickbares.', en: 'Marketing site 3–6 weeks. Web app MVP 6–12 weeks. AI tool on your data 4–10 weeks, depending on how tidy the data is. Internal software 8–14 weeks. You see something clickable in the first week.' } },
    { q: { de: 'Wer baut es konkret?', en: 'Who actually builds it?' }, a: { de: 'Die zwei Gründer. Christian entwickelt und betreibt, Kathi verantwortet Design und Marke. Keine Junioren, die auf Ihrem Budget lernen, kein Account-Manager zwischen Ihnen und der Arbeit, keine Weitergabe an Dritte.', en: 'The two founders. Christian builds and runs, Kathi does design and brand. No juniors learning on your budget, no account manager between you and the work, no subcontracting.' } },
    { q: { de: 'Ist KI bei Ihnen mehr als ein Schlagwort?', en: 'Is AI more than a buzzword here?' }, a: { de: 'Wir betreiben ein eigenes KI-Produkt: md-recall, Projektgedächtnis für Software-Teams – live und self-hosted. Die Konsole auf dieser Seite ist ebenfalls von uns.', en: 'We run our own AI product: md-recall, project memory for software teams — live and self-hosted. The console on this page is ours too.' } },
    { q: { de: 'Was passiert nach dem Launch?', en: 'What happens after launch?' }, a: { de: 'Wir bleiben. Das ist der Grund, warum das Studio aus zwei Senior-Leuten besteht und nicht aus fünfzehn: Auch im dritten Jahr erreichen Sie dieselben Personen. Wartung, Änderungen, neue Funktionen – ohne erneutes Einarbeiten.', en: 'We stay. That is why the studio is two senior people rather than fifteen: in year three you still reach the same people. Maintenance, changes, new features — no re-onboarding.' } },
    { q: { de: 'Können wir selbst hosten?', en: 'Can we host it ourselves?' }, a: { de: 'Ja – für alles, was Ihre Daten berührt, empfehlen wir es. Self-hosted, Ihre Schlüssel, Ihre Hardware. Kein Lock-in, keine Lizenz pro Nutzer. Sie erhalten Repository und Dokumentation.', en: 'Yes — and for anything touching your data we recommend it. Self-hosted, your keys, your hardware. No lock-in, no per-seat licence. You get the repository and the documentation.' } },
    { q: { de: 'Wann sind wir die falsche Wahl?', en: 'When are we the wrong choice?' }, a: { de: 'Wenn Sie bis Montag zwanzig Leute brauchen – wir sind zwei. Wenn Sie das günstigste Angebot suchen – das werden wir nicht sein. Wenn Sie täglich jemanden vor Ort brauchen – wir sitzen in Bayern und arbeiten remote.', en: 'If you need twenty people on it by Monday — we are two. If you want the cheapest bid — we will not be it. If you need someone on site every day — we are in Bavaria and work remotely.' } }
  ];
